#!/bin/bash# &lt;https://archlinuxarm.org/platforms/armv8/broadcom/raspberry-pi-3&gt;echo -e &quot;

Arch Linux ARM to SD Card&quot;echo -e &quot;For the Raspberry Pi 3, if you want to use the unofficial arm64 variant.&quot;echo -e &quot;(Otherwise use the Raspberry Pi 2 version of this script!)

&quot;if [[ $EUID -ne 0 ]]; then   echo &quot;This script must be run as root&quot; 1&gt;&amp;2   exit 1fiecho -e &quot;
All drives on this computer:
&quot;ls -1 /dev/sd?echo -e &quot;
Last messages in syslog:
&quot;dmesg | tailecho -e &quot;
Choose sd card (like /dev/sdX):
&quot;read SDCARDecho -e &quot;

Current partitioning of $SDCARD:
&quot;parted $SDCARD printecho -e &quot;

You chose $SDCARD
Are you sure to continue? Press Ctrl-C to abort!&quot;readcd /tmpecho -e &quot;
Downloading the Arch Linux ARM root filesystem (if needed):
&quot;URL=https://mirrors.ustc.edu.cn/archlinuxarm/os/ArchLinuxARM-rpi-3-latest.tar.gz# Sometimes the download server is slow. In that case, try a different one instead:#URL=http://de7.mirror.archlinuxarm.org/os/ArchLinuxARM-rpi-3-latest.tar.gzFNAME=$(basename &quot;$URL&quot;)FSIZE=$(curl --head --location --silent &quot;$URL&quot; --write-out &#x27;%&#123;http_code&#125; %&#123;size_download&#125; 
&#x27; | tac | grep -m1 Content-Length | cut -f 2 -d&#x27; &#x27; | tr -d &#x27;&#x27;)if [ -n &quot;$FNAME&quot; ]then  CURSIZE=$(wc -c &lt;&quot;$FNAME&quot;)  if [ $CURSIZE -ne $FSIZE ]; then    rm &quot;$FNAME&quot;    echo &quot;Removing any downloaded and leftover Arch Linux ARM image&quot;  fificurl --location --remote-name --time-cond &quot;$FNAME&quot; &quot;$URL&quot;if [ $? -ne 0 ]; then  echo &quot;Could not download the image file, please check the mirror&quot;  exit 1fiecho -e &quot;
Unmounting partitions found on $&#123;SDCARD&#125;
&quot;for MOUNT in $&#123;SDCARD&#125;?do  echo $MOUNT  umount $MOUNTdoneparted -s $SDCARD unit s printparted -s $SDCARD mktable msdosparted -s $SDCARD mkpart primary fat32 8192s 128MiBparted -s $SDCARD mkpart primary 128MiB 100%parted -s $SDCARD unit s printmkfs.vfat $&#123;SDCARD&#125;1mkfs.ext4 $&#123;SDCARD&#125;2rm -rf bootrm -rf rootmkdir bootmkdir rootmount $&#123;SDCARD&#125;1 bootmount $&#123;SDCARD&#125;2 rootecho -e &quot;
Extracting the root filesystem
&quot;bsdtar -xpf ArchLinuxARM-rpi-3-latest.tar.gz -C rootsyncecho -e &quot;
Moving boot files to the first partition
&quot;mv root/boot/* bootecho -e &quot;
Unmounting the two partitions
&quot;umount boot rootrmdir boot rootecho &quot;Insert the SD card into the Raspberry Pi , connect ethernet, and apply 5V power.&quot;echo &quot;Use the serial console or SSH to the IP address given to the board by your router. The username/password combination is alarm/alarm. The default root password is &#x27;root&#x27;.&quot;cd -

